(936, 'ssa_settings_json', '{\"capacity\":{\"enabled\":false,\"schema_version\":\"2020-04-28\"},\"installed\":{\"schema_version\":\"2023-06-19\",\"blackout_dates\":true,\"support\":true,\"advanced_scheduling\":true,\"calendar_events\":true,\"capacity\":false,\"developer\":true,\"google_calendar\":false,\"license\":false,\"mailchimp\":false,\"notifications\":true,\"offline_payments\":false,\"payments\":false,\"paypal\":false,\"reminders\":false,\"sms\":false,\"staff\":false,\"stripe\":false,\"styles\":true,\"tracking\":false,\"translation\":true,\"webhooks\":false,\"webex\":false,\"woocommerce\":false,\"zoom\":false,\"resources\":false,\"booking_flows\":false},\"global\":{\"enabled\":false,\"wizard_completed\":\"2026-10-11 04:29:22\",\"timezone_string\":\"Asia\\/Saigon\",\"country_code\":\"\",\"start_of_week\":\"1\",\"date_format\":\"j F, Y\",\"time_format\":\"g:i a\",\"admin_email\":\"dieulinh16506@gmail.com\",\"admin_phone\":false,\"staff_name\":\"nhom5_qtri\",\"company_name\":\"Website cung c\\u1ea5p \\u0111\\u1ed3ng ph\\u1ee5c doanh nghi\\u1ec7p b2b\",\"last_updated\":\"2026-10-11 04:29:23\",\"booking_post_id\":\"\",\"edit_appointment_page_id\":0,\"should_display_new_booking_app_banner\":\"\",\"schema_version\":\"2024-02-09\"},\"notifications\":{\"enabled\":true,\"notifications\":[{\"appointment_types\":[],\"id\":1791692176,\"schema\":\"2019-04-02\",\"sent_to\":[\"{{admin_email}}\"],\"title\":\"Email (Admin)\",\"subject\":\"{{ Appointment.customer_information.Name }} just booked an appointment\",\"message\":\"<p>{{ Appointment.customer_information.Name }} just booked an appointment on {{ Global.home_url }} <\\/p>\\n<p>Appointment Details: <br \\/>\\nStarting at {{ Appointment.business_start_date }} <\\/p>\\n<p>{% if instructions %}<br \\/>\\nInstructions: {{ instructions|raw }} <br \\/>\\n{% endif %}<\\/p>\\n<p>{% if Appointment.web_meeting_url %}<br \\/>\\nAt your appointment time, join the meeting using this link: {{ Appointment.web_meeting_url }}{% endif %}<\\/p>\\n<p>Type: {{ Appointment.AppointmentType.title|raw }} <\\/p>\\n<p>Customer details: <br \\/>\\n{{ Appointment.customer_information_summary }}<\\/p>\\n\",\"trigger\":\"appointment_booked\",\"type\":\"email\",\"when\":\"after\",\"duration\":0},{\"appointment_types\":[],\"id\":1791692177,\"schema\":\"2019-04-02\",\"sent_to\":[\"{{customer_email}}\"],\"subject\":\"Your appointment details\",\"message\":\"<p>Hi {{ Appointment.customer_information.Name }}, <\\/p>\\n<p>This is a confirmation of the appointment you just booked on {{ Global.site_url }} <\\/p>\\n<p>Appointment scheduled for {{ Appointment.customer_start_date }} <\\/p>\\n<p>{% if instructions %}<br \\/>\\nInstructions: {{ instructions|raw }} <br \\/>\\n{% endif %}<\\/p>\\n<p>{% if Appointment.web_meeting_url %}<br \\/>\\nAt your appointment time, join the meeting using this link: {{ Appointment.web_meeting_url }}{% endif %}<\\/p>\\n<p>Type: {{ Appointment.AppointmentType.title|raw }} <\\/p>\\n<p>Your details: <br \\/>\\n{{ Appointment.customer_information_summary }}<\\/p>\\n<p>If you need to cancel or change your appointment, you can do so by visiting this link: <br \\/>\\n{{ Appointment.public_edit_url }}<\\/p>\\n\",\"title\":\"Email (Customer)\",\"trigger\":\"appointment_booked\",\"type\":\"email\",\"when\":\"after\",\"duration\":0},{\"appointment_types\":[],\"id\":1791692178,\"schema\":\"2019-04-02\",\"sent_to\":[\"{{admin_email}}\"],\"title\":\"Email (Admin)\",\"subject\":\"{{ Appointment.customer_information.Name }} just canceled an appointment\",\"message\":\"<p>Your appointment \\\"{{ Appointment.AppointmentType.title|raw }}\\\" with {{ Appointment.customer_information.Name }} has been canceled <\\/p>{% if cancelation_note %}<p>{% if canceled_by_name %} {{ canceled_by_name }} left a note: {% else %}Note: {% endif %}{{ cancelation_note }} <\\/p>{% endif %}\\n<p>*** Canceled *** <br \\/>\\nAppointment Details: <br \\/>\\n{{ Appointment.business_start_date }} <\\/p>\\n<p>Type: {{ Appointment.AppointmentType.title|raw }} <\\/p>\\n<p>Customer details: <br \\/>\\n{{ Appointment.customer_information_summary }}<\\/p>\\n\",\"trigger\":\"appointment_canceled\",\"type\":\"email\",\"when\":\"after\",\"duration\":0},{\"appointment_types\":[],\"id\":1791692179,\"schema\":\"2019-04-02\",\"sent_to\":[\"{{customer_email}}\"],\"subject\":\"Your appointment has been canceled\",\"message\":\"<p>Hi {{ Appointment.customer_information.Name }},<br \\/>\\nYour appointment \\\"{{ Appointment.AppointmentType.title|raw }}\\\" (booked on {{ Global.home_url }}) has been canceled<\\/p>{% if cancelation_note %}<p>{% if canceled_by_name %} {{ canceled_by_name }} left a note: {% else %}Note: {% endif %}{{ cancelation_note }} <\\/p>{% endif %}\\n\",\"title\":\"Email (Customer)\",\"trigger\":\"appointment_canceled\",\"type\":\"email\",\"when\":\"after\",\"duration\":0}],\"schema_version\":\"2018-09-18 18:30\",\"last_updated\":\"2026-10-11 04:16:16\"},\"calendar_events\":{\"enabled\":false,\"event_type_customer\":{\"title\":\"{{ Appointment.AppointmentType.title }} ({{ Global.company_name }})\",\"location\":\"{{ location }}\",\"details\":\"<p>{% if Appointment.web_meeting_url %}<br \\/>\\nThis event has a web meeting:{{ Appointment.web_meeting_url }}<br \\/>\\n{% endif %}<\\/p>\\n<p>{% if instructions %}<br \\/>\\nInstructions: {{ instructions|raw }} <br \\/>\\n{% endif %}<\\/p>\\n<p>{% if Appointment.AppointmentType.description %}<br \\/>\\n{{ Appointment.AppointmentType.description }}<br \\/>\\n{% endif %}<\\/p>\\n<p>Need to make changes to this event? <br \\/>\\n{{ Appointment.public_edit_url }}<\\/p>\\n\"},\"event_type_individual_shared\":{\"title\":\"{{ customer_name }} + {{ Global.company_name }}: {{ Appointment.AppointmentType.title }}\",\"location\":\"{{ location }}\",\"details\":\"<p>{% if Appointment.web_meeting_url %}<br \\/>\\nThis event has a web meeting:{{ Appointment.web_meeting_url }}<br \\/>\\n{% endif %}<\\/p>\\n<p>Your details: <br \\/>\\n{{ Appointment.customer_information_summary }}<\\/p>\\n<p>Need to make changes to this event? <br \\/>\\n{{ Appointment.public_edit_url }}<\\/p>\\n\"},\"event_type_group_shared\":{\"title\":\"{{ Appointment.AppointmentType.title }} ({{ Global.company_name }})\",\"location\":\"{{ location }}\",\"details\":\"<p>{% if Appointment.web_meeting_url %}<br \\/>\\nThis event has a web meeting:{{ Appointment.web_meeting_url }}<br \\/>\\n{% endif %}<\\/p>\\n<p>Attendees:{{ attendees_list }}<\\/p>\\n\"},\"event_type_individual_admin\":{\"title\":\"{{ customer_name }} - {{ Appointment.AppointmentType.title }}\",\"location\":\"{{ location }}\",\"details\":\"<p>{% if Appointment.web_meeting_url %}<br \\/>\\nThis event has a web meeting:{{ Appointment.web_meeting_url }}<br \\/>\\n{% endif %}<\\/p>\\n<p>Customer details: <br \\/>\\n{{ Appointment.customer_information_summary }}<\\/p>\\n<p>Need to make changes to this event? <br \\/>\\n{{ Appointment.public_edit_url }}<\\/p>\\n\"},\"event_type_group_admin\":{\"title\":\"{{ Appointment.AppointmentType.title }}\",\"location\":\"{{ location }}\",\"details\":\"<p>{% if Appointment.web_meeting_url %}<br \\/>\\nThis event has a web meeting:{{ Appointment.web_meeting_url }}<br \\/>\\n{% endif %}<\\/p>\\n<p>Attendees:{{ attendees_list }}<\\/p>\\n\"},\"schema_version\":\"2021-09-23 17:50\",\"last_updated\":\"2026-10-11 04:16:16\"},\"developer\":{\"enabled\":true,\"enqueue_everywhere\":false,\"require_proof_token\":false,\"separate_appointment_type_availability\":false,\"beta_updates\":false,\"quick_connect_gcal_mode\":false,\"display_appointment_revisions\":false,\"capacity_availability\":false,\"cache_availability\":false,\"disable_availability_caching\":false,\"rate_limiting\":false,\"object_cache\":false,\"debug_mode\":false,\"ssa_debug_mode\":false,\"display_capacity_available\":false,\"remove_data_on_uninstall\":false,\"schema_version\":\"2026-07-17\"},\"advanced_scheduling\":{\"enabled\":false,\"schema_version\":\"2018-09-04\"},\"blackout_dates\":{\"enabled\":false,\"dates\":[],\"schema_version\":\"2018-02-20\"},\"staff\":{\"enabled\":false,\"schema_version\":\"2019-12-26.2\"},\"styles\":{\"enabled\":true,\"font\":\"Roboto\",\"accent_color\":\"rgba(139, 195, 74, 1)\",\"background\":\"rgba(255, 255, 255, 1)\",\"padding\":\"1rem\",\"contrast\":false,\"css\":\"\",\"schema_version\":\"2018-10-23\"},\"translation\":{\"enabled\":true,\"locales\":[],\"schema_version\":\"2019-10-15\"},\"last_updated\":\"2026-10-11 04:16:16\"}', 'auto'),
